// tests/flow.test.js      run with:  npm test        (needs the C++ engine built, NOT MongoDB)
//
// Demonstrates and checks the two dispatch situations:
//   1. enough resources      -> dispatched at once, the priority queue is not used
//   2. not enough resources  -> reports wait in the priority queue, highest score first
// plus: traffic is generated by the backend, and a traffic change re-routes units on their way.

const test = require("node:test");
const assert = require("node:assert/strict");
const { installFakeModels, call } = require("./helpers");

installFakeModels();

const engine = require("../utils/cppEngine");
const cityMap = require("../utils/cityMap");
const summary = require("../utils/resourceSummary");
const emergencies = require("../controllers/emergencyController");
const traffic = require("../controllers/trafficController");
const city = require("../controllers/cityController");
const arrivalWatcher = require("../utils/arrivalWatcher");
const Emergency = require("../models/Emergency");

const report = (title, type, locationNode, peopleCount) =>
  call(emergencies.createEmergency, { body: { title, type, locationNode, address: title, peopleCount } });
const resolve = (id) => call(emergencies.deleteEmergency, { params: { id } });
const queue = async () => (await call(emergencies.getPriorityQueue)).body;

test.after(() => engine.stop());

test.before(async () => {
  await engine.start();
  await cityMap.load();
  await call(traffic.clearTraffic);
});

test("the backend generates the traffic (random, repeatable with a seed)", async () => {
  const a = await call(traffic.randomizeTraffic, { body: { seed: 7 } });
  const b = await call(traffic.randomizeTraffic, { body: { seed: 7 } });
  assert.equal(a.statusCode, 200);
  assert.equal(a.body.roads.length, 84);
  assert.deepEqual(a.body.roads.map((r) => r.load), b.body.roads.map((r) => r.load));
  assert.ok(a.body.roads.every((r) => r.level && "color" in r && r.speedFactor >= 1));
  await call(traffic.clearTraffic);
});

test("the map for the frontend carries everything it draws", async () => {
  const res = await call(city.getCityMap);
  assert.equal(res.body.nodes.length, 48);
  assert.equal(res.body.roads.length, 84);
  assert.ok(res.body.roads.every((r) => r.d && r.pts.length > 2));
  assert.ok(res.body.rivers.length && res.body.areas.length && res.body.stationTypes.fire);
});

test("1. enough resources: dispatched straight away, nothing waits in the queue", async () => {
  await call(emergencies.resetEmergencies);

  const before = await summary.buildSummary();
  const fire = (await report("Shop fire", "fire", "clock", 3)).body;
  const medical = (await report("Road crash", "medical", "rail", 7)).body;

  assert.equal(fire.status, "assigned");
  assert.equal(fire.queuePosition, null);
  assert.ok(fire.routePath.length >= 1 && fire.totalSeconds > 0);

  assert.equal(medical.status, "assigned"); // 7 people -> 3 ambulances
  assert.equal(medical.unitsNeeded, 3);
  assert.equal(medical.queuePosition, null);
  assert.equal(medical.dispatchedBy, "Central Medical Control");

  assert.deepEqual(await queue(), []); // the priority queue stayed empty

  const after = await summary.buildSummary();
  assert.equal(after.fire.available, before.fire.available - 1);
  assert.equal(after.medical.available, before.medical.available - 3);
});

test("2. not enough resources: the priority queue decides who gets the next free unit", async () => {
  await call(emergencies.resetEmergencies);
  const start = await summary.buildSummary();
  assert.equal(start.fire.total, 9);
  assert.equal(start.fire.available, 9);

  // use up all 9 fire engines
  const fillers = [];
  for (let i = 1; i <= 9; i++) fillers.push((await report("Filler fire " + i, "fire", "clock", 1)).body);
  assert.ok(fillers.every((f) => f.status === "assigned"));
  assert.equal((await summary.buildSummary()).fire.available, 0);

  // two more fires: there is no engine left, so both wait
  const low = (await report("LOW: small fire", "fire", "rajpur", 1)).body; // score 1*5 + 2 = 7
  const high = (await report("HIGH: big fire", "fire", "dalanwala", 10)).body; // score 10*5 + 2 = 52

  assert.equal(low.status, "pending");
  assert.equal(high.status, "pending");
  assert.equal(low.priorityScore, 7);
  assert.equal(high.priorityScore, 52);

  // although LOW was reported first, HIGH is first in the queue
  const q = await queue();
  assert.deepEqual(q.map((e) => e.title), ["HIGH: big fire", "LOW: small fire"]);
  assert.deepEqual(q.map((e) => e.queuePosition), [1, 2]);

  // one fire is resolved: the freed engine goes to HIGH, not to LOW
  const freed = await resolve(fillers[0].id);
  assert.deepEqual(freed.body.dispatchedFromQueue.map((e) => e.title), ["HIGH: big fire"]);
  assert.equal((await call(emergencies.getEmergencyById, { params: { id: high.id } })).body.status, "assigned");
  const stillWaiting = (await call(emergencies.getEmergencyById, { params: { id: low.id } })).body;
  assert.equal(stillWaiting.status, "pending");
  assert.equal(stillWaiting.queuePosition, 1);

  // another one is resolved: now LOW gets its engine
  const freed2 = await resolve(fillers[1].id);
  assert.deepEqual(freed2.body.dispatchedFromQueue.map((e) => e.title), ["LOW: small fire"]);
  assert.deepEqual(await queue(), []);
});

test("a report no hospital can ever take is unassigned, not kept waiting", async () => {
  await call(emergencies.resetEmergencies);
  const huge = (await report("Mass casualty", "medical", "clock", 40)).body;
  assert.equal(huge.status, "unassigned");
  assert.equal(huge.queuePosition, null);
});

test("a traffic change re-routes a unit that is on its way (done by the backend)", async () => {
  await call(emergencies.resetEmergencies);
  await call(traffic.clearTraffic);

  const e = (await report("Fire near Rajpur", "fire", "rajpur", 1)).body;
  assert.equal(e.status, "assigned");
  const route = e.routePath;
  assert.ok(route.length >= 2);

  // jam every road of the route
  for (let i = 0; i + 1 < route.length; i++) {
    const road = (await call(city.getTraffic)).body.find(
      (r) => (r.from === route[i] && r.to === route[i + 1]) || (r.from === route[i + 1] && r.to === route[i])
    );
    await call(traffic.setRoad, { params: { id: road.id }, body: { level: "heavy" } });
  }

  const after = (await call(emergencies.getEmergencyById, { params: { id: e.id } })).body;
  assert.ok(after.totalSeconds > e.totalSeconds, "the trip should now take longer");
  assert.ok(after.trafficDelaySeconds > 0 || after.routePath.join() !== route.join());
  await call(traffic.clearTraffic);
});

test("the server (not the browser) marks a report ON SCENE when its unit arrives", async () => {
  await call(emergencies.resetEmergencies);
  const e = (await report("Robbery", "police", "clock", 1)).body;
  assert.equal(e.status, "assigned");

  await arrivalWatcher.check(); // just sent: not there yet
  assert.equal((await call(emergencies.getEmergencyById, { params: { id: e.id } })).body.status, "assigned");

  // pretend the unit was sent long ago
  const doc = await Emergency.findById(e.id);
  doc.assignments.police.dispatchedAt = new Date(Date.now() - (e.totalSeconds + 5) * 1000);
  await arrivalWatcher.check();

  const after = (await call(emergencies.getEmergencyById, { params: { id: e.id } })).body;
  assert.equal(after.status, "ON SCENE");
  assert.equal(after.displayStatus, "ON SCENE");
});
